#!/usr/bin/env python3
"""One-shot deterministic Denton action-routing runtime packager.

Run only on agent/civic-gps-denton-actions. It replaces the three changed
runtime text artifacts with preverified exact bytes, rebuilds the runtime ZIP
with fixed metadata, verifies the expected SHA-256, and rewrites repository
chunks. The release PR deletes this script after packaging.
"""
from __future__ import annotations
import base64
import hashlib
import json
import zlib
from pathlib import Path
from zipfile import ZIP_DEFLATED, ZipFile, ZipInfo

ROOT = Path(__file__).resolve().parents[1]
GPS = ROOT / "civic_gps"
ZIP_PATH = ROOT / "civic_gps_runtime.zip"
PARTS = ROOT / "civic_gps_runtime_parts"
EXPECTED_SHA = "ea4e10ac250582f01e0a5eabb74837cd987325dfafb30c4111121c4e7c950c9b"
PAYLOADS = {
    "README.md": "",
    "civic_gps_action_registry_denton_v0.1.json": "",
    "registry.json": "",
}

for name, encoded in PAYLOADS.items():
    raw = zlib.decompress(base64.b64decode(encoded))
    (GPS / name).write_bytes(raw)

registry = json.loads((GPS / "registry.json").read_text(encoding="utf-8"))
actions = json.loads((GPS / "civic_gps_action_registry_denton_v0.1.json").read_text(encoding="utf-8"))
assert registry["engine_version"] == "0.6.0"
assert registry["registry_artifact_version"] == "0.5.1"
assert registry["consumer_schema_version"] == "civic-gps-response/0.3.0"
assert actions["meta"]["route_count"] == 27
bundle = next(b for b in registry["bundles"] if b["adapter_id"] == "ADAPTER-TX-DENTON")
assert bundle["action_registry_files"] == ["civic_gps_action_registry_denton_v0.1.json"]
assert any(x.get("layer") == "denton_action_endpoints" and x.get("status") == "RELEASE_BACKED" for x in bundle["coverage_rules"])
assert any(x.get("gap_id") == "GAP-DENTON-GPS-003" and x.get("status") == "CLOSED" for x in bundle["known_gaps"])

with ZipFile(ZIP_PATH, "w") as zf:
    for path in sorted(GPS.iterdir(), key=lambda p: p.name):
        if not path.is_file() or path.name.startswith("."):
            continue
        info = ZipInfo(f"civic_gps/{path.name}", date_time=(2026, 8, 7, 0, 0, 0))
        info.compress_type = ZIP_DEFLATED
        info.create_system = 3
        info.external_attr = 0o100644 << 16
        zf.writestr(info, path.read_bytes())

digest = hashlib.sha256(ZIP_PATH.read_bytes()).hexdigest()
if digest != EXPECTED_SHA:
    raise SystemExit(f"runtime SHA mismatch: {digest} != {EXPECTED_SHA}")

PARTS.mkdir(exist_ok=True)
for old in PARTS.glob("part.*"):
    old.unlink()
blob = ZIP_PATH.read_bytes()
for i, offset in enumerate(range(0, len(blob), 8000)):
    (PARTS / f"part.{i:02d}").write_bytes(blob[offset:offset+8000])

print(f"PASS: Denton action runtime {digest}; {len(actions['actions'])} routes; {len(blob)} bytes; {len(list(PARTS.glob('part.*')))} chunks")
